search.script:
if (response.status !== 1) throw new Error('status');
var info = (response.data && response.data.info) || [];
var all = [];
for (var i = 0; i < info.length; i++) {
  all.push(info[i]);
  var group = info[i].group || [];
  for (var j = 0; j < group.length; j++) { all.push(group[j]); }
}
return all.map(function (s) {
  var hash = String(s.hash || '');
  var ms = Math.round((s.duration || 0) * 1000);
  var title = String(s.songname || '');
  return {
    id: hash + '|' + ms + '|' + title,
    title: title,
    artist: String(s.singername || ''),
    album: String(s.album_name || ''),
    durationMs: ms
  };
});

lyrics.script:
if (response.status !== 200 || response.errcode !== 200) throw new Error('status');
var list = response.candidates || [];
if (!list.length) return null;
return { _fetchEncryptedLyrics: true, vars: list.slice(0, 5).map(function (c) { return { id: String(c.id), accesskey: String(c.accesskey) }; }) };
